/* SPDX-License-Identifier: GPL-3.0-only
 * ATT MTU and CCCD responses survive HCI mailbox backpressure.
 * Build: cc -std=c99 -Wall -Wextra -Werror -I. this.c ble_midi_host.c -o test
 */
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include "ble_midi_host.h"
static unsigned checks, failed;
#define CHECK(x) do { checks++; if (!(x)) { failed++; fprintf(stderr,"FAIL:%d %s\n",__LINE__,#x); } } while (0)
typedef struct { int reject; unsigned acl; uint8_t type, data[80]; unsigned len; } bus_t;
static int send_packet(uint8_t t,const uint8_t *p,uint16_t n,void *ctx)
{
    bus_t *b=ctx;
    if(b->reject)return -1;
    b->type=t;b->len=n;
    if(n>sizeof b->data)return -1;
    memcpy(b->data,p,n);
    if(t==BLEH_H4_ACL)b->acl++;
    return 0;
}
static void setup(bleh_t*h,bus_t*b)
{
    memset(b,0,sizeof *b);
    bleh_init(h,send_packet,b,"X0X37",0);
    h->state=BLEH_CONNECTED;h->conn=0x40;
    h->acl_total=h->credits=4;
}
static void request(bleh_t*h,const uint8_t*p,unsigned n)
{
    uint8_t b[40]={0x40,0x20,0,0,0,0,4,0};
    CHECK(n<=23);
    if(n>23)return;
    b[2]=b[4]=(uint8_t)n;b[2]+=4;
    memcpy(b+8,p,n);
    bleh_rx(h,BLEH_H4_ACL,b,(uint16_t)(8+n));
}
static void test_mtu(void)
{
    bleh_t h;bus_t b;
    const uint8_t mtu[]={2,23,0},cccd[]={18,7,0,1,0},off[]={0x52,6,0,0x80,0x80,0x80,60,0};
    bleh_msg_t m={0};
    setup(&h,&b);b.reject=1;
    request(&h,mtu,sizeof mtu);
    CHECK(h.mtu_req==23 && b.acl==0);
    request(&h,cccd,sizeof cccd);
    CHECK(h.cccd[0]==0); /* competing request cannot overwrite pending response */
    request(&h,off,sizeof off);
    CHECK(bleh_midi_next(&h,&m)==1 && m.b[0]==0x80 && m.b[1]==60);
    for(unsigned i=0;i<100;i++)bleh_poll(&h);
    CHECK(b.acl==0);
    b.reject=0;bleh_poll(&h);
    CHECK(b.acl==1 && b.type==BLEH_H4_ACL && b.len==11);
    if(b.len==11)CHECK(b.data[8]==3 && b.data[9]==23 && b.data[10]==0);
    for(unsigned i=0;i<10;i++)bleh_poll(&h);
    CHECK(b.acl==1); /* no duplicate, works before CCCD enabled */
}
static void test_cccd(void)
{
    bleh_t h;bus_t b;
    const uint8_t cccd[]={18,7,0,1,0};
    setup(&h,&b);b.reject=1;
    request(&h,cccd,sizeof cccd);
    CHECK(h.cccd[0]==1 && b.acl==0);
    b.reject=0;bleh_poll(&h);
    CHECK(b.acl==1 && b.len==9 && b.data[8]==19);
    CHECK(h.credits==3);
}
static void test_disconnect(void)
{
    bleh_t h;bus_t b;
    const uint8_t mtu[]={2,23,0},bye[]={5,4,0,0x40,0,0x13};
    setup(&h,&b);b.reject=1;
    request(&h,mtu,sizeof mtu);
    bleh_rx(&h,BLEH_H4_EVT,bye,sizeof bye);
    b.reject=0;
    for(unsigned i=0;i<10;i++)bleh_poll(&h);
    CHECK(b.acl==0); /* response from prior connection may never replay */
}
int main(void)
{
    test_mtu();test_cccd();test_disconnect();
    printf("ble ATT retry: %u checks, %u failures\n",checks,failed);
    return failed?1:0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* MID-12/MID-13: AUTO/INTERNAL idle clocks cannot wrap ext_since and
 * mistake 27 hours without input for a sub-millisecond MIDI tick. */
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include "sequencer.h"

static unsigned checks, failed, mode, frames;
#define CHECK(x) do { ++checks; if (!(x)) { ++failed; if (failed <= 24u) \
    fprintf(stderr, "FAIL mode=%u frames=%u line=%d: %s\n", mode, frames, __LINE__, #x); } } while (0)

static pattern_t patterns[NPAT];
static seq_sink_t sink;
static void setup(seq_t *s, unsigned m)
{
    memset(patterns, 0, sizeof(patterns));
    memset(&sink, 0, sizeof(sink));
    seq_init(s, patterns);
    s->clk_src = (uint8_t)m;
    s->clk_cur = (uint8_t)m;
}
static void advance(seq_t *s, uint32_t n)
{
    while (n) {
        uint32_t k = n < frames ? n : frames;
        CHECK(k > 0u && k <= frames);
        seq_advance(s, k, &sink);
        n -= k;
    }
}
static void idle_saturates(void)
{
    seq_t s;
    setup(&s, mode);
    s.ext_since = 2u * FS - 1u;
    advance(&s, frames);
    uint32_t cap = s.ext_since;
    CHECK(cap >= 2u * FS && cap <= 2u * FS + frames);
    advance(&s, 3u * FS); /* hours later this must still be the last-clock sentinel */
    CHECK(s.ext_since == cap);
    CHECK(s.ext_period == 0u);
    CHECK(s.ext_bpm == 125.0f);
}
static void idle_rollover_then_clock(void)
{
    seq_t s;
    setup(&s, SEQ_CLK_AUTO);
    s.ext_since = UINT32_MAX - 16u; /* legacy live AUTO idle at ~27.05 hours */
    s.ext_now = UINT32_MAX - 16u;
    advance(&s, 64u);
    CHECK(s.ext_since > FS); /* do not turn a 27-hour silence into 47 samples */
    CHECK(s.ext_now == 47u); /* free-running wrap must remain valid */
    CHECK(seq_clk_take(&s, 0xF8u, 0u) == 1);
    CHECK(seq_midi_rt(&s, 0xF8u) == 1);
    advance(&s, 1u);
    CHECK(s.ext_period == 0u); /* one clock cannot measure a whole new tempo */
    CHECK(s.ext_bpm == 125.0f);
    CHECK(s.ext_since == 0u);
    /* A valid subsequent tick interval must still establish a measured tempo. */
    advance(&s, FS / 48u);
    CHECK(seq_clk_take(&s, 0xF8u, 0u) == 1);
    CHECK(seq_midi_rt(&s, 0xF8u) == 1);
    advance(&s, 1u);
    CHECK(s.ext_period != 0u);
    CHECK(s.ext_bpm >= 119.0f && s.ext_bpm <= 121.0f);
}
/* Real user path: an idle INTERNAL session is changed back to AUTO/EXTERNAL
 * immediately before Loopy reconnects. Do not infer tempo from counter wrap. */
static void internal_idle_mode_change_then_clock(unsigned target)
{
    seq_t s;
    setup(&s, SEQ_CLK_INT);
    s.ext_since = UINT32_MAX - 16u;
    s.ext_now = UINT32_MAX - 16u;
    advance(&s, 64u);
    CHECK(s.ext_since > FS);  /* silence is not a 47-sample MIDI interval */
    CHECK(s.ext_now == 47u);  /* the free-running clock still wraps */
    s.clk_src = (uint8_t)target;
    advance(&s, 1u);         /* firmware applies clock-source change in ISR */
    CHECK(s.clk_cur == target);
    CHECK(s.ext_period == 0u);
    CHECK(seq_clk_take(&s, 0xF8u, 0u) == 1);
    CHECK(seq_midi_rt(&s, 0xF8u) == 1);
    advance(&s, 1u);
    CHECK(s.ext_period == 0u);    /* first clock cannot measure a tempo */
    CHECK(s.ext_bpm == 125.0f);
    advance(&s, FS / 48u);        /* genuine 120 BPM quarter-tick interval */
    CHECK(seq_clk_take(&s, 0xF8u, 0u) == 1);
    CHECK(seq_midi_rt(&s, 0xF8u) == 1);
    advance(&s, 1u);
    CHECK(s.ext_period != 0u);
    CHECK(s.ext_bpm >= 119.0f && s.ext_bpm <= 121.0f);
}

/* Early first Clock is not a tempo measurement: boot and INT->AUTO/EXT. */
static void early_first_clock(unsigned target, int from_internal)
{
    seq_t s;
    setup(&s, from_internal ? SEQ_CLK_INT : SEQ_CLK_AUTO);
    advance(&s, FS / 20u); /* 50 ms of silence before changing CLOCK SOURCE */
    s.clk_src = (uint8_t)target;
    advance(&s, FS / 20u); /* 50 ms before first Loopy MIDI F8 */
    CHECK(s.clk_cur == target);
    CHECK(seq_clk_take(&s, 0xF8u, 0u) == 1);
    CHECK(seq_midi_rt(&s, 0xF8u) == 1);
    advance(&s, 1u);
    CHECK(s.ext_q == 1u);
    CHECK(s.ext_period == 0u); /* no previous tick to measure */
    CHECK(s.ext_bpm == 125.0f);
    advance(&s, FS / 48u); /* 120 BPM: 918.75 samples per MIDI clock */
    CHECK(seq_clk_take(&s, 0xF8u, 0u) == 1);
    CHECK(seq_midi_rt(&s, 0xF8u) == 1);
    advance(&s, 1u);
    CHECK(s.ext_period != 0u);
    CHECK(s.ext_bpm >= 119.0f && s.ext_bpm <= 121.0f);
}
/* The 0.5-second dropout also resets the beat ring. Reconnect must not
 * average that missing-clock gap into the next tempo measurement. */
static void first_clock_after_dropout(unsigned target)
{
    seq_t s;
    setup(&s, SEQ_CLK_AUTO);
    s.clk_src = (uint8_t)target;
    advance(&s, FS); /* first clock occurs well after power-up */
    CHECK(seq_clk_take(&s, 0xF8u, 0u) == 1);
    CHECK(seq_midi_rt(&s, 0xF8u) == 1);
    advance(&s, 1u);
    advance(&s, FS / 48u);
    CHECK(seq_clk_take(&s, 0xF8u, 0u) == 1);
    CHECK(seq_midi_rt(&s, 0xF8u) == 1);
    advance(&s, 1u);
    CHECK(s.ext_period != 0u);
    CHECK(s.ext_bpm >= 119.0f && s.ext_bpm <= 121.0f);
    advance(&s, FS / 2u + 64u); /* trigger AUTO fallback or EXTERNAL wait */
    CHECK(s.ext_q == 0u && s.ext_nb == 0u);
    float before = s.ext_bpm;
    CHECK(seq_clk_take(&s, 0xF8u, 0u) == 1);
    CHECK(seq_midi_rt(&s, 0xF8u) == 1);
    advance(&s, 1u);
    CHECK(s.ext_q == 1u);
    CHECK(s.ext_bpm == before); /* first returning F8 measures no tempo */
    advance(&s, FS / 48u);
    CHECK(seq_clk_take(&s, 0xF8u, 0u) == 1);
    CHECK(seq_midi_rt(&s, 0xF8u) == 1);
    advance(&s, 1u);
    CHECK(s.ext_bpm >= 119.0f && s.ext_bpm <= 121.0f);
}


/* Bluetooth may deliver several 0xF8 ticks in one audio callback. The first
 * packet after silence establishes phase, not an artificial tempo; all ticks
 * must remain counted, and the next *separately timed* tick can measure BPM. */
static void first_clock_burst(unsigned target, unsigned input, unsigned burst)
{
    seq_t s;
    setup(&s, target);
    advance(&s, FS / 10u);  /* early Loopy connection, 100 ms after boot */
    for (unsigned i = 0; i < burst; i++) {
        CHECK(seq_clk_take(&s, 0xF8u, input) == 1);
        CHECK(seq_midi_rt(&s, 0xF8u) == 1);
    }
    advance(&s, 1u);         /* one audio callback, multiple F8 inputs */
    CHECK(s.ext_q == burst);
    CHECK(s.ext_nb == 0u);
    CHECK(s.ext_period == 0u);   /* no independently measured interval */
    CHECK(s.ext_bpm == 125.0f);
    CHECK(s.clk_lock == input + 1u);
    CHECK(seq_clk_take(&s, 0xF8u, input ^ 1u) == 0); /* no double-rate input */
    advance(&s, FS / 48u); /* next true 120-BPM clock tick */
    CHECK(seq_clk_take(&s, 0xF8u, input) == 1);
    CHECK(seq_midi_rt(&s, 0xF8u) == 1);
    advance(&s, 1u);
    CHECK(s.ext_q == burst + 1u);
    CHECK(s.ext_period != 0u);
    CHECK(s.ext_bpm >= 119.0f && s.ext_bpm <= 121.0f);
}

int main(void)
{
    const unsigned partitions[] = {1u, 64u, 1024u};
    for (unsigned i = 0; i < 3u; ++i) {
        frames = partitions[i];
        for (mode = SEQ_CLK_AUTO; mode <= SEQ_CLK_EXT; ++mode)
            idle_saturates();
        mode = SEQ_CLK_AUTO;
        idle_rollover_then_clock();
        internal_idle_mode_change_then_clock(SEQ_CLK_AUTO);
        internal_idle_mode_change_then_clock(SEQ_CLK_EXT);
        early_first_clock(SEQ_CLK_AUTO, 0);
        early_first_clock(SEQ_CLK_EXT, 0);
        early_first_clock(SEQ_CLK_AUTO, 1);
        early_first_clock(SEQ_CLK_EXT, 1);
        first_clock_after_dropout(SEQ_CLK_AUTO);
        first_clock_after_dropout(SEQ_CLK_EXT);
        for (unsigned burst = 2u; burst <= 5u; burst++) {
            first_clock_burst(SEQ_CLK_AUTO, 0u, burst); /* USB */
            first_clock_burst(SEQ_CLK_AUTO, 1u, burst); /* Bluetooth */
            first_clock_burst(SEQ_CLK_EXT, 0u, burst);
            first_clock_burst(SEQ_CLK_EXT, 1u, burst);
        }
    }
    fprintf(stderr, "seq AUTO idle wrap: %u/%u checks %s\n", checks-failed, checks, failed?"FAILED":"PASSED");
    return failed ? 1 : 0;
}

/* SPDX-License-Identifier: GPL-3.0-only
 * The SMK-37 "<" and ">" buttons: the route and the hold repeat. Pure functions, no hardware access.
 * main_fm1.c (smk_arrows) and the host simulator use this file. tests/smk_arrows_test.c tests it. */
#pragma once
#include <stdint.h>

#ifndef ARW_FN
#define ARW_FN __attribute__((minsize, noinline, unused))   /* small code: the app area is almost full */
#endif

/* Hold repeat in a menu: the first repeat 400 ms after the press, then one step each 80 ms.
 * The frame tick is 16 ms or more, so a repeat comes on the first frame at or after its time.
 * The repeat keeps the 80 ms grid. A frame that comes more than 80 ms late gives one step only, not a burst. */
#define ARW_FIRST_MS 400u
#define ARW_NEXT_MS 80u

/* where the arrows go: nothing, SELECT (one detent for each press), or the menu value (with repeat).
 * ARW_NONE in clip mode with no menu: the clip keys page takes the arrows there (ck_controls, CLP-76). */
enum { ARW_NONE, ARW_SELECT, ARW_MENU };

/* menu: a menu list that the main code owns is open (GLO or a page list, also in clip mode).
 * clip: clip mode is on. home: HOME is held (SELECT is the tempo). */
static inline uint32_t arw_route(uint32_t menu, uint32_t clip, uint32_t home)
{
    return home ? ARW_NONE : menu ? ARW_MENU : clip ? ARW_NONE : ARW_SELECT;
}

typedef struct {
    uint8_t prev;         /* the arrows at the last frame: bit 0 "<", bit 1 ">" */
    uint8_t rep;          /* the arrow that repeats (1 or 2), 0 none */
    uint16_t due;         /* the time of the next repeat (ms, the low 16 bits) */
} arw_t;

/* One frame. now: the arrows that are down (bit 0 "<", bit 1 ">"). Return the steps: -1, 0 or +1
 * (ARW_SELECT: a press of each arrow, as before; both at once give 0). Only ARW_MENU repeats.
 * A press of the other arrow while one is held stops the repeat. */
ARW_FN static int32_t arw_frame(arw_t *a, uint32_t now, uint32_t route, uint32_t ms)
{
    uint32_t pr = now & ~(uint32_t)a->prev;
    int32_t d = (int32_t)(pr >> 1 & 1u) - (int32_t)(pr & 1u);
    a->prev = (uint8_t)now;
    if (route != ARW_MENU || now != a->rep)
        a->rep = 0;
    if (route == ARW_NONE)
        return 0;
    if (route == ARW_MENU) {
        if (pr && (now == 1u || now == 2u)) {
            a->rep = (uint8_t)now;
            a->due = (uint16_t)(ms + ARW_FIRST_MS);
        } else if (a->rep && (int16_t)(uint16_t)(ms - a->due) >= 0) {
            a->due = (uint16_t)(a->due + ARW_NEXT_MS);
            if ((int16_t)(uint16_t)(ms - a->due) >= 0)
                a->due = (uint16_t)(ms + ARW_NEXT_MS);
            d = a->rep == 2u ? 1 : -1;
        }
    }
    return d;
}

#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Host regression for the actual firmware plat_slot conversion and slot admission.

Extracts the exact plat_slot C function from the source tree, compiles it
alongside the original slots.c validator with GCC/Clang, and checks real sampleio
serialized slot headers at all supported Q16 rates. The rest of the target
unity build and the physical device are NOT tested by this standalone probe.
"""
from __future__ import annotations
import argparse
import re
import struct
import subprocess
import sys
import tempfile
import zlib
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / "tools"))
import sampleio  # noqa: E402


def function_source(text: str) -> str:
    pattern = r'^const uint8_t \*plat_slot\(int k, int z, uint32_t \*nsamples, uint32_t \*rate, char name\[9\]\)\n\{'
    m = re.search(pattern, text, re.M)
    if not m:
        raise RuntimeError("plat_slot function signature not found in source; NOT TESTED")
    brace_pos = text.index('{', m.start())
    depth = 0
    for i in range(brace_pos, len(text)):
        if text[i] == '{':
            depth += 1
        elif text[i] == '}':
            depth -= 1
            if depth == 0:
                return text[m.start():i + 1]
    raise RuntimeError("unterminated plat_slot function; NOT TESTED")


def run(cc: str, flags: list[str]):
    text = (ROOT / "firmware/src/app/plat_fm1.c").read_text()
    fn = function_source(text)
    with tempfile.TemporaryDirectory(prefix="x0x37-slot-rate-") as td:
        tmp = Path(td)
        cases = [22050, 44100, 65536, 88200, 96000, 176400]
        for rate in cases:
            header, data = sampleio.user_slot("RATE", [([0] * 64, 60, None, None)], rate=rate, slot_size=0x14000)
            if len(header) != 480 or zlib.crc32(data) != struct.unpack_from("<I", header, 20)[0]:
                raise RuntimeError(f"invalid serialized fixture for {rate} Hz; NOT TESTED")
            (tmp / f"slot-{rate}.bin").write_bytes(header.ljust(512, b'\0') + data)
        src = tmp / "slot_rate.c"
        src.write_text('''#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
/* Real validator from production source; target virtual flash represented by RAM. */
static uint32_t mem[3][0x1E000/4];
#define BOARD_SMK37 1
#define SMP_USER_XIP(k) ((const uint8_t *)mem[(k)])
#include "firmware/src/app/slots.c"
/* Exact production plat_slot function inserted below (not rewritten in the test). */
#line 189 "firmware/src/app/plat_fm1.c"
''' + fn + '''
int main(int argc, char **argv)
{
    int failures = 0;
    for (int a = 1; a < argc; a++) {
        memset(mem, 0, sizeof mem);
        FILE *f = fopen(argv[a], "rb");
        if (!f) return 90;
        if (!fread(mem[0], 1, 544, f)) { fclose(f); return 91; }
        fclose(f);
        smp_user_scan(0);
        if (usr_nz[0] != 1) { fprintf(stderr,"FAIL validator rejected sample %s\\n",argv[a]); return 92; }
        const smp_user_hdr_t *h = (const smp_user_hdr_t *)mem[0];
        uint32_t n=0, actual=0;
        char name[9];
        const uint8_t *adpcm = plat_slot(0, 0, &n, &actual, name);
        uint32_t expected = (uint32_t)(((uint64_t)h->zone[0].rate * 44100u + 32768u) >> 16);
        fprintf(stderr,"ADMITTED q16=%u expected=%u actual=%u n=%u data=%s\\n",
                h->zone[0].rate,expected,actual,n,adpcm ? "yes":"no");
        if (!adpcm || n != 64 || actual != expected) failures++;
    }
    /* Check every Q16 value the real firmware slot validator admits. */
    const smp_user_hdr_t *h = (const smp_user_hdr_t *)mem[0];
    smp_user_hdr_t *w = (smp_user_hdr_t *)mem[0];
    int sweep_bad = 0;
    for (uint32_t q = 1; q <= (4u << 16); q++) {
        w->zone[0].rate = q;
        smp_user_scan(0);
        if (usr_nz[0] != 1) return 94;
        uint32_t ns=0, hz=0;
        char nm[9];
        const uint8_t *adpcm = plat_slot(0, 0, &ns, &hz, nm);
        uint32_t expected = (uint32_t)(((uint64_t)h->zone[0].rate * 44100u + 32768u) >> 16);
        if (!adpcm || ns != 64 || hz != expected) {
            if (sweep_bad < 4) fprintf(stderr,"SWEEP FAIL q16=%u expected=%u observed=%u\\n",q,expected,hz);
            sweep_bad++;
        }
    }
    fprintf(stderr,"TOTAL supported-Q16 checks=%u failures=%d; file cases=%d\\n",
            4u << 16, sweep_bad, failures);
    return failures || sweep_bad ? 1 : 0;
}
''')
        binary = tmp / 'rate_test'
        cmd = [cc, '-std=c11', '-O1', '-g', '-Wall', '-Wextra', '-Werror',
               '-Wno-unused-function', '-Wno-unused-parameter', '-fsanitize=address,undefined,bounds',
               '-fno-sanitize-recover=all', '-I', str(ROOT), str(src), '-o', str(binary)] + flags
        print('COMPILE', *cmd, flush=True)
        subprocess.run(cmd, check=True)
        args = [str(binary)] + [str(tmp / f"slot-{rate}.bin") for rate in cases]
        print('EXEC', *args, flush=True)
        subprocess.run(args, check=True)
        print('PASS', len(cases), 'valid source-serialized sample rates, source-extracted plat_slot, slot_scan', flush=True)


if __name__ == '__main__':
    p = argparse.ArgumentParser()
    p.add_argument('--cc', default='gcc')
    a = p.parse_args()
    run(a.cc, [])

#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Full MIDI-out MQ must retain Note Off under a CC flood.

Extracts production midi_out_event (+ shared ring helper) from usb.c. A queued
Note On plus a full ring of CCs must still accept Note Off by displacing a CC.
"""
from pathlib import Path
import re
import subprocess
import tempfile

ROOT = Path(__file__).resolve().parents[2]
u = (ROOT / "firmware/src/usb.c").read_text()


def function(source, name):
    m = re.search(r"^[^\n]*\b" + re.escape(name) + r"\([^\n]*\)\s*\{", source, re.M)
    if not m:
        raise ValueError("Missing " + name)
    depth, end = 1, m.end()
    while depth:
        if end >= len(source):
            raise ValueError("Unterminated " + name)
        depth += (source[end] == "{") - (source[end] == "}")
        end += 1
    return source[m.start() : end]


# Shared Note Off predicate + ring put (production names).
start = u.index("/* CIN 8, or CIN 9 with velocity 0")
end = u.index("void midi_send_note(")
chunk = u[start:end]
# Drop midi_in_* (inbound harness owns those); keep out path + shared helpers.
chunk = re.sub(
    r"/\* Enqueue into midi_in_q\.[^*]*\*/\s*static int midi_in_put\(uint32_t pkt\)\s*\{[^}]*\}\s*",
    "",
    chunk,
    count=1,
    flags=re.S,
)

src = (
    "#include <stdint.h>\n#include <stdio.h>\n"
    "#define RING_PUBLISH() ((void)0)\n"
    "#define MQ 64u\n"
    "static uint32_t midi_out_q[MQ];\n"
    "static volatile uint32_t mo_w, mo_r;\n"
    "static struct { int config; } usb;\n"
    + chunk
    + r"""
