/* SPDX-License-Identifier: GPL-3.0-only */
/* Chicago Fx Type = Hall — per-voice insert (not SEND / Mix reverb theft).
 *
 * Factory Hall rows (Snail, …) need diffuse reverb colour on the dry 303 voice
 * for strong-relative spectrum. AU compare previously rendered dry native303
 * while Hall only stole the shared Mix reverb bus (and host render never ran
 * fxbus).
 *
 * Compact mono Schroeder: 4 int16 combs + 2 float allpasses (~2 KB/voice).
 * Edit1 → wet (floor 0.5; former Mix send). Edit2 → decay (low values floor
 * like the old SEND RvDec map). Fixed damp / return level. No libm. */
#pragma once
#include <stdint.h>
#include <string.h>
#include "chicago_fx.h"

#ifndef CHI_HALL_SR
#define CHI_HALL_SR 44100.0f
#endif

#define CHI_HALL_C0 379
#define CHI_HALL_C1 421
#define CHI_HALL_C2 457
#define CHI_HALL_C3 503
#define CHI_HALL_COMB_N (CHI_HALL_C0 + CHI_HALL_C1 + CHI_HALL_C2 + CHI_HALL_C3)
#define CHI_HALL_AP0 139
#define CHI_HALL_AP1 107

typedef struct {
    int16_t comb[CHI_HALL_COMB_N];
    float ap0[CHI_HALL_AP0];
    float ap1[CHI_HALL_AP1];
    float cdmp[4];
    uint16_t cpos[4];
    uint16_t apos0, apos1;
    float fb;
    float damp;
    float wet;
    float lvl;
} chi_hall_t;

static inline int16_t chi_hall_q12(float x)
{
    /* 12-bit sat toward zero — same density law as fxbus combs. */
    if (x > 7.999f)
        x = 7.999f;
    if (x < -8.0f)
        x = -8.0f;
    return (int16_t)(x * 2048.0f);
}

static inline void chi_hall_set(chi_hall_t *h, uint8_t e1, uint8_t e2, float sr)
{
    float send, dec;
    (void)sr;
    if (!h)
        return;
    send = (float)e1 * (1.0f / 127.0f);
    /* Former SEND: tone < 20 → RvDec pot 73 (mid-long). */
    if (e2 < 20)
        dec = 0.62f;
    else
        dec = 0.45f + (float)e2 * (1.0f / 127.0f) * 0.45f;
    h->fb = dec;
    h->damp = 0.42f;
    h->wet = send < 0.5f ? 0.5f : send;
    h->lvl = 0.67f; /* former fixed RvLvl ≈ 85/127 */
}

static inline void chi_hall_init(chi_hall_t *h)
{
    if (!h)
        return;
    memset(h, 0, sizeof(*h));
    h->fb = 0.0f;
    h->damp = 0.42f;
    h->wet = 0.0f;
    h->lvl = 0.67f;
}

/* In-place mono insert. wet=0 is a no-op. */
static inline void chi_hall_process(chi_hall_t *h, float *buf, int n)
{
    static const uint16_t cl[4] = { CHI_HALL_C0, CHI_HALL_C1, CHI_HALL_C2, CHI_HALL_C3 };
    float wet, dry_g, fb, damp, lvl;
    int16_t *cb[4];
    uint16_t cpos[4], a0, a1;
    float *ap0, *ap1;
    int k, c;
    if (!h || !buf || n <= 0)
        return;
    wet = h->wet;
    if (wet <= 0.0f)
        return;
    dry_g = 1.0f - wet;
    fb = h->fb;
    damp = h->damp;
    lvl = h->lvl;
    cb[0] = h->comb;
    cb[1] = cb[0] + CHI_HALL_C0;
    cb[2] = cb[1] + CHI_HALL_C1;
    cb[3] = cb[2] + CHI_HALL_C2;
    ap0 = h->ap0;
    ap1 = h->ap1;
    for (c = 0; c < 4; c++)
        cpos[c] = h->cpos[c];
    a0 = h->apos0;
    a1 = h->apos1;
    for (k = 0; k < n; k++) {
        float x = buf[k];
        float acc = 0.0f, y, bo;
        for (c = 0; c < 4; c++) {
            int16_t *b = cb[c];
            uint16_t p = cpos[c];
            float cy = (float)b[p] * (1.0f / 2048.0f);
            acc += cy;
            h->cdmp[c] = cy + (h->cdmp[c] - cy) * damp;
            b[p] = chi_hall_q12(x + h->cdmp[c] * fb);
            cpos[c] = (uint16_t)(p + 1u >= cl[c] ? 0u : p + 1u);
        }
        y = acc * 0.25f;
        bo = ap0[a0];
        ap0[a0] = y + bo * 0.5f;
        y = bo - y * 0.5f;
        a0 = (uint16_t)(a0 + 1u >= CHI_HALL_AP0 ? 0u : a0 + 1u);
        bo = ap1[a1];
        ap1[a1] = y + bo * 0.5f;
        y = bo - y * 0.5f;
        a1 = (uint16_t)(a1 + 1u >= CHI_HALL_AP1 ? 0u : a1 + 1u);
        buf[k] = dry_g * x + wet * y * lvl;
    }
    for (c = 0; c < 4; c++)
        h->cpos[c] = cpos[c];
    h->apos0 = a0;
    h->apos1 = a1;
}

static inline int chi_fx_is_hall_insert(uint8_t type)
{
    return type == CHI_FX_HALL;
}

// SPDX-License-Identifier: GPL-3.0-only
// Copyright (C) 2026 Leo Kuroshita (@kurogedelic), Hügelton Instruments
//
// The FM-1 USB-MIDI update protocol (M-UPGRADE compatible) over WebMIDI.
// Step 1: the running firmware reads parts of the package and stages the update
// loader. Step 2: the loader reads the whole image and writes it. In both steps
// the device sends cmd 0x30 read requests on the logical image and we answer.

const HS_QUERY = [0xF0, 0x00, 0x32, 0x45, 0x00, 0x00, 0x00, 0x40, 0x7F, 0xF7];
const UPGRADE = [0xF0, 0x22, 0x24, 0x35, 0x7F, 0xF7];
const MAXDATA = 512;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const IS_OTA = (id) => /^ota-/i.test(id.model);
// the SMK-37 Pro, SMK-37 Elite, MKE-P37, Starrykey 37 Play and the SMK-37+VA mod: one keyboard under several model
// names, so a package for one runs on all of them; an FM-1 is another device
const SMK_FAMILY = /^(ota-)?(SMK-37[ +].*|MKE-P37|STARRYKEY-37.*)$/i;
export const sameKeyboard = (a, b) => a === b || (SMK_FAMILY.test(a) && SMK_FAMILY.test(b));   // two models

// errors carry a code the pages translate: notfound, model, stopped, noloader, lost, noreturn,
// mismatch (detail: the identity the device reports), badreq
function fail(code, msg, detail = "") { const e = new Error(msg); e.code = code; e.detail = detail; return e; }

export function pack7(data) {
  const out = []; let acc = 0, nb = 0;
  for (const b of data) {
    acc |= b << nb; nb += 8;
    while (nb >= 7) { out.push(acc & 0x7F); acc >>>= 7; nb -= 7; }
  }
  if (nb) out.push(acc & 0x7F);
  return out;
}

export function unpack7(s) {
  const out = []; let acc = 0, nb = 0;
  for (const b of s) {
    acc |= (b & 0x7F) << nb; nb += 7;
    while (nb >= 8) { out.push(acc & 0xFF); acc >>>= 8; nb -= 8; }
  }
  return out;
}

function response(addr, data, fl = 0) {
  const len = data.length;
  const body = [0x00, 0x59, 0x30, (len + 8) & 0xFF, ((len + 8) >> 8) & 0xFF, 0, fl,
    addr & 0xFF, (addr >>> 8) & 0xFF, (addr >>> 16) & 0xFF, (addr >>> 24) & 0xFF,
    len & 0xFF, (len >> 8) & 0xFF, 0, ...data];
  let s = 0;
  for (let i = 6; i < body.length; i++) s += body[i];
  body.push(~s & 0xFF);
  return [0xF0, ...pack7(body), 0xF7];
}

function parseRequest(pkt) {
  if (pkt[0] !== 0xF0 || pkt[pkt.length - 1] !== 0xF7) return null;
  const u = unpack7(pkt.slice(1, -1));
  if (u.length !== 15 || u[0] !== 0 || u[1] !== 0x59 || u[2] !== 0x30) return null;
  let s = 0;
  for (let i = 6; i < 14; i++) s += u[i];
  if ((~s & 0xFF) !== u[14]) return null;
  return { fl: u[6], addr: (u[7] | (u[8] << 8) | (u[9] << 16) | (u[10] << 24)) >>> 0, len: u[11] | (u[12] << 8) | (u[13] << 16) };
}

function parseIdentity(pkt) {
  if (pkt[0] !== 0xF0 || pkt[pkt.length - 1] !== 0xF7) return null;
  const wire = pkt.slice(1, -1);
  if (wire.some((b) => b & 0x80)) return null;       // SysEx data must be seven-bit
  const d = unpack7(wire);
  // ota_send_msg(0x11): 27 identity bytes, a 24-bit declared length, then ~sum(payload).
  if (d.length !== 34 || d[0] !== 0 || d[1] !== 0x59 || d[2] !== 0x11 ||
      d[3] !== 27 || d[4] !== 0 || d[5] !== 0) return null;
  let sum = 0;
  for (let i = 6; i < 33; i++) sum += d[i];
  if ((~sum & 0xFF) !== d[33]) return null;
  // Reject extra packed padding bits as well as status bytes hidden in the payload.
  if (pack7(d).some((b, i) => b !== wire[i])) return null;
  const txt = String.fromCharCode(...d.slice(6, 33)).replace(/\0+$/, "");
  const m = /^([^_]+)_(\d+)$/.exec(txt);
  return m ? { text: txt, model: m[1], version: parseInt(m[2], 10) } : null;
}

// one MIDI in/out pair with a SysEx queue
class Link {
  constructor(input, output) {
    this.input = input; this.output = output; this.q = []; this.waiter = null;
    this.onMessage = (ev) => {
      if (ev.data[0] !== 0xF0) return;
      this.q.push(Array.from(ev.data));
      if (this.waiter) { const w = this.waiter; this.waiter = null; w(); }
    };
    // A MIDI input may already have an application handler. Do not replace it.
    if (typeof input.addEventListener === "function" &&
        typeof input.removeEventListener === "function") {
      this.useEvents = true;
      input.addEventListener("midimessage", this.onMessage);
    } else {
      // Compatibility with legacy/mock inputs that only expose the property.
      this.useEvents = false;
      const previous = input.onmidimessage;
      this.previousHandler = previous;
      this.installedHandler = (ev) => {
        this.onMessage(ev);
        if (typeof previous === "function") previous.call(input, ev);
      };
      input.onmidimessage = this.installedHandler;
    }
  }
  get lost() { return this.input.state === "disconnected" || this.output.state === "disconnected"; }
  // false when the port is gone (unplugged): WebMIDI throws on a disconnected output
  send(bytes) {
    try { this.output.send(bytes); return true; } catch (_) { return false; }
  }
  drain() { this.q.length = 0; }
  async read(ms) {
    if (!this.q.length) {
      let tm;
      await Promise.race([new Promise((r) => { this.waiter = r; }), new Promise((r) => { tm = setTimeout(r, ms); })]);
      clearTimeout(tm);
      this.waiter = null;
    }
    return this.q.shift() || null;
  }
  close() {
    if (this.useEvents) this.input.removeEventListener("midimessage", this.onMessage);
    else if (this.input.onmidimessage === this.installedHandler)
      this.input.onmidimessage = this.previousHandler;
  }
}

async function handshake(link, tries = 3) {
  link.drain();
  for (let t = 0; t < tries; t++) {
    if (!link.send(HS_QUERY)) return null;
    const end = Date.now() + 1000;
    while (Date.now() < end) {
      const p = await link.read(end - Date.now());
      if (!p) break;
      const id = parseIdentity(p);
      if (id) return id;
    }
  }
  return null;
}

export class Updater {
  constructor(access, log) {
    this.access = access;
    this.log = log || (() => {});
    // Port accepted by the last fail-closed transition wait (loader or restart).
    this.returnedPort = null;
    // Running ports observed while the selected unit is still in the loader (before reboot).
    this._beforeRunning = null;
  }

  _portPairs() {
    const ins = [...this.access.inputs.values()].filter((p) => p.state !== "disconnected");
    const outs = [...this.access.outputs.values()].filter((p) => p.state !== "disconnected");
    const pairs = [];
    for (const input of ins) {
      if (!/fm-1|smk|elite|mke-p37|starry|felucca|melodee|fomni|x0x|makkuro|snoop|vector|vox|ota|composite|sinco|usb-midi/i.test(input.name || "")) continue;   // never probe other gear
      // Names alone do not prove physical identity. Refuse duplicate or
      // mismatched port labels instead of guessing which keyboard receives MIDI.
      if (ins.filter((p) => p.name === input.name).length !== 1) continue;
      const matching = outs.filter((p) => p.name === input.name);
      if (matching.length !== 1) continue;
      pairs.push({ input, output: matching[0], name: input.name });
    }
    return pairs;
  }

  // every in/out pair with the same port name that answers the handshake
  async find(filter) {
    for (const { input, output, name } of this._portPairs()) {
      try { await input.open(); await output.open(); } catch (_) { continue; }
      const link = new Link(input, output);
      const id = await handshake(link, 2);
      if (id && (!filter || filter(id))) return { link, id, name };
      link.close();
    }
    return null;
  }

  // Port names that answer and match filter (every link closed). Used to snapshot before a transition.
  // skip: a port name already held open; do not reopen it (would steal onmidimessage from the live link).
  async matchingPorts(filter, skip = null) {
    const names = [];
    for (const { input, output, name } of this._portPairs()) {
      if (skip != null && name === skip) continue;
      try { await input.open(); await output.open(); } catch (_) { continue; }
      const link = new Link(input, output);
      try {
        const id = await handshake(link, 2);
        if (id && (!filter || filter(id))) names.push(name);
      } finally { link.close(); }
    }
    return names;
  }

  async openPort(name, filter) {
    const pair = this._portPairs().find((p) => p.name === name);
    if (!pair) return null;
    try { await pair.input.open(); await pair.output.open(); } catch (_) { return null; }
    const link = new Link(pair.input, pair.output);
    const id = await handshake(link, 2);
    if (id && (!filter || filter(id))) return { link, id, name };
    link.close();
    return null;
  }

  // Fail-closed transition wait: accept exactly one newly appeared matching port.
  // before: port names that already matched filter before the transition.
  // Returns that device, or null when none appear before the timeout.
  // Throws when more than one new matching port appears. Never returns a port in before.
  async waitFor(filter, ms, before) {
    const end = Date.now() + ms;
    const prior = new Set(before);
    while (Date.now() < end) {
      const names = await this.matchingPorts(filter);
      const newcomers = names.filter((n) => !prior.has(n));
      if (newcomers.length > 1) {
        throw fail("model", "more than one new device appeared after the update transition; disconnect other keyboards and try again. Nothing was written");
      }
      if (newcomers.length === 1) {
        const dev = await this.openPort(newcomers[0], filter);
        if (dev) { this.returnedPort = newcomers[0]; return dev; }
      }
      await sleep(1000);
    }
    return null;
  }

  // Reconnect after a verified transition: same newly-appeared rule vs other ports.
  async reconnectAfter(filter, ms) {
    const known = this.returnedPort;
    const before = (await this.matchingPorts(filter)).filter((n) => n !== known);
    return this.waitFor(filter, ms, before);
  }

  // serve read requests until the device asks for one of the finish addresses; stops early
  // when the port disappears (lost: true) instead of waiting out idleMs
  async serve(link, image, finishAddr, idleMs, onProgress) {
    let served = 0, last = Date.now();
    for (;;) {
      const pkt = await link.read(1000);
      if (!pkt) {
        if (link.lost) return { served, finished: false, lost: true };
        if (Date.now() - last > idleMs) return { served, finished: false };
        continue;
      }
      const r = parseRequest(pkt);
      if (!r) continue;
      last = Date.now();
      if (r.addr === 0xE0000000 || r.addr === 0xF0000000) {
        link.send(response(r.addr, [...new TextEncoder().encode("success"), 0]));
        if (r.addr === finishAddr) return { served, finished: true };
        continue;
      }
      if (r.len > MAXDATA || r.addr + r.len > image.length) throw fail("badreq", `bad request ${r.addr.toString(16)}+${r.len}`);
      await sleep(10);
      if (!link.send(response(r.addr, Array.from(image.subarray(r.addr, r.addr + r.len)), r.fl))) {
        return { served, finished: false, lost: true };
      }
      served++;
      if (onProgress) onProgress(served, r.addr);
    }
  }

  // full install: running firmware -> loader -> new firmware
  async install(image, product, onStep) {
    const step = onStep || (() => {});
    const dev = await this.find((id) => !IS_OTA(id));
    if (!dev) throw fail("notfound", "FM-1 not found (USB cable, and no other app using it?)");
    const [model] = product.split("_");
    if (!sameKeyboard(dev.id.model, model)) { dev.link.close(); throw fail("model", `the device is ${dev.id.text}, the package is for ${product}`); }
    const beforeLoaders = await this.matchingPorts(IS_OTA, dev.name);
    step("start", dev.id.text);
    dev.link.send(UPGRADE);
    await sleep(2000);
    const s1 = await this.serve(dev.link, image, 0xE0000000, 8000, (n) => step("verify", n));
    dev.link.close();
    if (!s1.finished) throw fail(s1.lost ? "lost" : "stopped", `the device ${s1.lost ? "was disconnected" : "stopped"} after ${s1.served} requests: nothing was written`);
    step("loader");
    await sleep(3000);
    const ota = await this.waitFor((id) =>
      IS_OTA(id) && sameKeyboard(id.model.replace(/^ota-/i, ""), model), 30000, beforeLoaders);
    if (!ota) throw fail("noloader", "the update loader did not appear. Replug the USB cable and press Install again: the device stays in update mode until it is finished.");
    // Reject a loader from another keyboard family, even if discovery changes.
    if (!IS_OTA(ota.id) || !sameKeyboard(ota.id.model.replace(/^ota-/i, ""), model)) {
      ota.link.close();
      throw fail("model", `the loader is ${ota.id.text}, the package is for ${product}`, ota.id.text);
    }
    const s2 = await this.write(ota, image, step);
    if (!s2.finished) throw fail(s2.lost ? "lost" : "stopped", `the loader ${s2.lost ? "was disconnected" : "stopped"} after ${s2.served} requests. Replug and press Install again to resume.`);
    const beforeRunning = this._beforeRunning || [];
    step("reboot");
    await sleep(3000);
    // A different connected keyboard is not evidence that the target rebooted.
    // In particular, stock/manual mode must not report false success on mismatch.
    const back = await this.waitFor((id) => !IS_OTA(id) && sameKeyboard(id.model, model), 40000, beforeRunning);
    if (!back || !sameKeyboard(back.id.model, model))
      throw fail("noreturn", "the target keyboard did not come back: power-cycle it");
    back.link.close();
    if (back.id.text !== product) throw fail("mismatch", `installed, but the device reports ${back.id.text}`, back.id.text);
    step("done", back.id.text);
    return back.id.text;
  }

  // step 2 with the loader found by find()/waitFor()
  async write(ota, image, step) {
    // Snapshot other running keyboards while this unit is still in the loader.
    this._beforeRunning = await this.matchingPorts((id) => !IS_OTA(id), ota.name);
    ota.link.send(UPGRADE);
    await sleep(2000);
    const s2 = await this.serve(ota.link, image, 0xF0000000, 180000, (n) => step("write", n));
    ota.link.close();
    return s2;
  }

  // resume: the device is already in update mode (loader) -> true when the write finished. product: the
  // package's identity; the loader's model must match it by install()'s rule (sameKeyboard): an SMK's loader
  // never gets an FM-1 image, and without the identity nothing is written
  async resume(image, onStep, product = "") {
    const ota = await this.find(IS_OTA);
    if (!ota) return false;
    if (!product || !sameKeyboard(ota.id.model.replace(/^ota-/i, ""), product.split("_")[0])) {
      ota.link.close();
      throw fail("model", `the device is in the update mode of ${ota.id.text}, the package is for ${product || "an unknown model"}`, ota.id.text);
    }
    return (await this.write(ota, image, onStep || (() => {}))).finished;
  }
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* Chicago pitch bend + damper (AU ids 20–21) — performance aux on native303.
 *
 * Stored in sound_t after SEND FX (CHI_PBEND / CHI_DAMPER). Pitch bend is a
 * live ±2 semitone offset around centre pot 64 — it does not rewrite TUNE.
 * The SMK pitch wheel is the live source: while it is off centre it writes
 * CHI_PBEND (not TUNE) and on release the saved pot returns. Damper (sustain)
 * defers live/MIDI note-off while pot ≥ 64; pattern gates ignore it.
 * Miami aux stays on WBL1 — not mapped here. */
#pragma once
#include <stdint.h>
#include "../dsp/x0x_param.h"
#include "chicago_fx.h" /* CHI_FX_END == 30 */

enum {
    CHI_PBEND = CHI_FX_END, /* 30 */
    CHI_DAMPER,
    CHI_AUX_END /* engine_nparams(T_303) == 32; fills NPARAMS_MAX */
};

enum { CHI_DAMP_OFF = 0, CHI_DAMP_ON = 1 };
/* Damper engages at pot ≥ 64 (AU 0.5). Factory banks leave damper at 0. */
#define CHI_DAMP_THRESH 64

/* Tables live in chicago_param_tables.c (one copy for engine.o + x0x.o). */
extern const x0x_param_t CHI_AUX_PARAMS[2];

/* AU / factory 0..255 → 0..127. */
static inline uint8_t chi_aux_from_byte(uint8_t v)
{
    return (uint8_t)(((uint32_t)v * 127u + 127u) / 255u);
}

static inline void chi_aux_decode_factory(const uint8_t pots[2], uint8_t out[2])
{
    out[0] = chi_aux_from_byte(pots[0]);
    out[1] = chi_aux_from_byte(pots[1]);
}

static inline void chi_aux_apply_factory_voice(uint8_t *voice_pots, const uint8_t factory_pots[2])
{
    uint8_t d[2];
    chi_aux_decode_factory(factory_pots, d);
    voice_pots[CHI_PBEND] = d[0];
    voice_pots[CHI_DAMPER] = d[1];
}

static inline int chi_damper_on(uint8_t pot)
{
    return pot >= CHI_DAMP_THRESH;
}

/* Semitone offset for pot 0..127 (±2 at the ends). */
static inline float chi_pbend_semitones(uint8_t pot)
{
    return ((float)((int)pot - 64) / 64.0f) * 2.0f;
}

/* Pitch-wheel deflection −63..63 (0 = spring centre) → CHI_PBEND pot.
 * 64 is no bend. The wheel does not add this onto TUNE. */
static inline int chi_pbend_from_wheel(int bend)
{
    if (bend < -63)
        bend = -63;
    if (bend > 63)
        bend = 63;
    return 64 + bend;
}

#!/usr/bin/env python3
# SPDX-License-Identifier: GPL-3.0-only
"""Full BLE MIDI-out mirror must retain Start/Continue/Stop under a CC flood.

Sibling of ble_out_noteoff_overflow_test.py (#600) and midi_mq_rt_overflow_test.py.
Extracts production ble_out (+ keep helpers) from ble.c. Notify backpressure must
not strand realtime transport into Loopy over BLE.
"""
from pathlib import Path
import re
import subprocess
import tempfile

ROOT = Path(__file__).resolve().parents[2]
b = (ROOT / "firmware/src/ble.c").read_text()


def function(source, name):
    m = re.search(r"^[^\n]*\b" + re.escape(name) + r"\([^\n]*\)\s*\{", source, re.M)
    if not m:
        raise ValueError("Missing " + name)
    depth, end = 1, m.end()
    while depth:
        if end >= len(source):
            raise ValueError("Unterminated " + name)
        depth += (source[end] == "{") - (source[end] == "}")
        end += 1
    return source[m.start() : end]


helpers = (
    function(b, "ble_out_is_note_off")
    + "\n"
    + function(b, "ble_out_is_rt_transport")
    + "\n"
    + function(b, "ble_out_pkt_is_keep")
)

src = (
    "#include <stdint.h>\n#include <stdio.h>\n"
    "#define RING_PUBLISH() ((void)0)\n"
    "#define BLE_OQ 56u\n"
    "static uint32_t ble_oq[BLE_OQ];\n"
    "static struct { volatile uint32_t ow, orr; union { int h; } host; } ble_r;\n"
    "static int ble_central_role, ble_host_on = 1, ble_want = 1;\n"
    "static int smc_ble_role_get(void) { return 0; }\n"
    "static int bleh_notifying(void *h) { (void)h; return 1; }\n"
    + helpers
    + "\n"
    + function(b, "ble_out")
    + r"""
static uint32_t mk(unsigned cin, unsigned st, unsigned d1, unsigned d2)
{
    return (cin & 15u) | (st << 8) | (d1 << 16) | (d2 << 24);
}

static int count_rt(unsigned st)
{
    unsigned n = 0;
    for (uint32_t i = ble_r.orr; i != ble_r.ow; i++) {
        uint32_t p = ble_oq[i % BLE_OQ];
        if ((p & 0xFu) == 0xFu && ((p >> 8) & 0xFFu) == st)
            n++;
    }
    return (int)n;
}

static int count_note_off(unsigned note)
{
    unsigned n = 0;
    for (uint32_t i = ble_r.orr; i != ble_r.ow; i++) {
        uint32_t p = ble_oq[i % BLE_OQ];
        if ((p & 0xFu) == 8u && ((p >> 16) & 0x7Fu) == note)
            n++;
    }
    return (int)n;
}

static int expect_rt_kept(unsigned st)
{
    ble_r.ow = ble_r.orr = 0;
    for (unsigned i = 0; i < BLE_OQ; i++)
        ble_out(mk(0xB, 0xB0, 16, i & 127u));
    ble_out(mk(0xF, st, 0, 0));
    if (ble_r.ow - ble_r.orr != BLE_OQ)
        return 13;
    if (count_rt(st) != 1)
        return 14;
    return 0;
}

static int expect_rt_does_not_displace_note_off(void)
{
    ble_r.ow = ble_r.orr = 0;
    ble_out(mk(8, 0x80, 60, 0x7F));
    for (unsigned i = 0; i < BLE_OQ - 1u; i++)
        ble_out(mk(0xB, 0xB0, 1, i & 127u));
    ble_out(mk(0xF, 0xFC, 0, 0));
    if (count_note_off(60) != 1)
        return 24;
    if (count_rt(0xFC) != 1)
        return 25;
    return 0;
}

static int expect_clock_still_drops(void)
{
    ble_r.ow = ble_r.orr = 0;
    for (unsigned i = 0; i < BLE_OQ; i++)
        ble_out(mk(0xB, 0xB0, 7, i & 127u));
    uint32_t before = ble_r.ow;
    ble_out(mk(0xF, 0xF8, 0, 0));
    if (ble_r.ow != before)
        return 32;
    if (count_rt(0xF8) != 0)
        return 33;
    return 0;
}

int main(void)
{
    int rc;
    if ((rc = expect_rt_kept(0xFC)) != 0) {
        printf("FAIL ble stop-kept rc=%d depth=%u stops=%d\n",
               rc, (unsigned)(ble_r.ow - ble_r.orr), count_rt(0xFC));
        return 1;
    }
    if ((rc = expect_rt_kept(0xFA)) != 0) {
        printf("FAIL ble start-kept rc=%d\n", rc);
        return 2;
    }
    if ((rc = expect_rt_kept(0xFB)) != 0) {
        printf("FAIL ble continue-kept rc=%d\n", rc);
        return 3;
    }
    if ((rc = expect_rt_does_not_displace_note_off()) != 0) {
        printf("FAIL ble rt-vs-noteoff rc=%d\n", rc);
        return 4;
    }
    if ((rc = expect_clock_still_drops()) != 0) {
        printf("FAIL ble clock-drop rc=%d\n", rc);
        return 5;
    }
    puts("ok");
    return 0;
}
"""
)
with tempfile.TemporaryDirectory(prefix="x0x-ble-out-rt-") as d:
    cpath = Path(d) / "t.c"
    cpath.write_text(src)
    exe = Path(d) / "t"
    subprocess.check_call(
        ["cc", "-std=c99", "-O2", "-Wall", "-Wextra", "-Werror", str(cpath), "-o", str(exe)]
    )
    raise SystemExit(subprocess.call([str(exe)]))

/* SPDX-License-Identifier: GPL-3.0-only */
/* In-place conversion of format-2 packed patterns to velocity-bearing steps. */
#include <stdio.h>
#include <string.h>
#include "../../firmware/src/app/project.c"

int main(void)
{
    uint8_t *raw = (uint8_t *)&proj + RAW_OFF;
    pattern2_t old;
    arrange_t arr;
    int p;
    memset(raw, 0, RAW_LEN);
    memset(&arr, 0, sizeof arr);
    /* Check the whole overlapping move, including fields far from the start. */
    for (p = 0; p < (int)sizeof arr; p++)
        ((uint8_t *)&arr)[p] = (uint8_t)(p * 37u + 11u);
    arr.song.len = 17;
    arr.song.bar[16].pat[TRK_BASS0] = 29;
    for (p = 0; p < NPAT; p++) {
        memset(&old, 0, sizeof old);
        old.drum[0].hit[0][0] = (uint32_t)p + 1u;
        old.bass[0].step[0].note = (uint8_t)(36 + p);
        old.bass[0].step[0].flags = G_NOTE | BS_SLIDE;
        old.bass[0].step[1].note = 99; /* A TIE's stored pitch must survive migration too. */
        old.bass[0].step[1].flags = G_TIE;
        old.bass[0].step[15].note = 12;
        old.bass[0].step[15].flags = G_TIE | BS_SLIDE | BS_ACCENT;
        old.bass[0].len = 16;
        old.bass[0].gen.seed = (uint32_t)(9000 + p);
        old.brk.slice_mode = p & 1; old.brk.rsv = (uint8_t)(128 + p);
        old.brk.slice[15] = 8;
        old.swing = (uint8_t)p;
        memcpy(raw + (uint32_t)p * sizeof old, &old, sizeof old);
    }
    memcpy(raw + NPAT * sizeof(pattern2_t), &arr, sizeof arr);
    stream_from2(&proj);
    migrate_break_counts(&proj, 2);
    for (p = 0; p < NPAT; p++)
        if (proj.pat[p].drum[0].hit[0][0] != (uint32_t)p + 1u ||
            proj.pat[p].bass[0].step[0].note != 36 + p ||
            proj.pat[p].bass[0].step[0].flags != (G_NOTE | BS_SLIDE) ||
            proj.pat[p].bass[0].step[1].note != 99 ||
            proj.pat[p].bass[0].step[1].flags != G_TIE ||
            proj.pat[p].bass[0].step[15].note != 12 ||
            proj.pat[p].bass[0].step[15].flags != (G_TIE | BS_SLIDE | BS_ACCENT) ||
            bstep_velocity(&proj.pat[p].bass[0].step[0]) != BASS_VELOCITY_DEFAULT ||
            proj.pat[p].bass[0].gen.seed != (uint32_t)(9000 + p) ||
            proj.pat[p].brk.slice_mode != 0 || proj.pat[p].brk.rsv != 128 + p ||
            proj.pat[p].brk.slice[15] != 8 || proj.pat[p].swing != p) {
            printf("format-2 migration failed at pattern %d\n", p);
            return 1;
        }
    if (memcmp(&proj.arr, &arr, sizeof arr) != 0) {
        puts("format-2 arrangement migration failed");
        return 1;
    }
    puts("303 format-2 stream migration: ok");
    return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* X0X 808 drum part: the 8W8 TR-808 engine (Charles Vestal and contributors,
 * GPL-3.0; the rim shot is Yoshinosuke Horiuchi's sc808, MIT) ported to the FM-1.
 *
 * Same circuit models, pot tables, defaults, kit trims, velocity law and hat
 * choke as 8W8's sc808_engine.cpp. What is NOT here: 8W8's own reverb, delay,
 * master drive / glue and note map (the firmware's fxbus does the sends and the
 * master), its mutes (the sequencer's business) and its state blob.
 *
 * ELEVEN TRACKS, sixteen sounds, the way the TR-808 itself does it: LT/MT/HT
 * each switch Tom / Conga, RS switches Rim / Claves and CP switches Clap /
 * Maracas. Every one of the sixteen sounds keeps its own pots (a conga keeps its
 * conga decay when the switch goes back to tom), and a track's knobs edit the
 * sound its switch selects. CH cuts OH (kit Choke switch, as 8W8).
 *
 * Mono, 44.1 kHz, C99, float, no libm, no allocation. Idle voices cost nothing;
 * the shared metal bank (six Schmitt squares feeding CB, CH, OH and CY) runs
 * only while one of those four is sounding.
 *
 * Threading: drum808_trigger / drum808_set are called between render blocks. */
#pragma once
#include <stdint.h>
#include "x0x_param.h"

enum { D8_BD, D8_SD, D8_LT, D8_MT, D8_HT, D8_RS, D8_CP, D8_CB, D8_CY, D8_OH, D8_CH, D8_NUM, D8_KIT = D8_NUM };

/* The velocity an UNACCENTED 808 hit corresponds to: 8W8's velocity line puts
 * the 4 V trigger floor (gain 1.0) at vel 1/1.992 with the kit's Accent pot at
 * its default. vel 1.0 is the accented hit (7.3 V). */
#define D8_VEL_NORMAL 0.502f

#define D8_MAX_BLOCK 256

/* the sixteen sounds, 8W8's lane order */
enum { D8S_BD, D8S_SD, D8S_LT, D8S_MT, D8S_HT, D8S_LC, D8S_MC, D8S_HC,
       D8S_RS, D8S_CL, D8S_MA, D8S_CP, D8S_CB, D8S_CH, D8S_OH, D8S_CY, D8S_NUM };
/* per-sound pot slots */
enum { D8P_LEVEL, D8P_TUNE, D8P_DECAY, D8P_DRIVE, D8P_DIST, D8P_REV, D8P_DLY,
       D8P_X1, D8P_X2, D8P_NUM };   /* X1/X2: BD tone/attack, SD snappy/tone, MA attack */

/* ---- DSP primitives ---------------------------------------------------- */
/* Biquads are transposed direct form II with the denominator stored as its
 * distance from (1 - z^-1)^2: a1 = -2 + e1, a2 = 1 + e2. At a 50 Hz resonance
 * a1 is -1.9999x, and a float a1 keeps only five of those digits; e1 and e2 are
 * computed from sin(w/2) directly and keep all of theirs. */
typedef struct { float b0, e1, e2, z1, z2; } d8_bp_t;               /* constant-peak bandpass */
typedef struct { float n0, n1, n2, e1, e2, z1, z2; } d8_bq_t;       /* general biquad */
typedef struct { float z[3]; } d8_bq3_t;                            /* Werner's 3rd-order BP (fixed coefs) */
typedef struct { float a, z, y; } d8_hp1_t;                         /* one-pole highpass */
typedef struct { uint32_t s1, s2, s3; } d8_rng_t;                   /* SuperCollider taus88 */

typedef struct {                    /* SuperCollider EnvGen.kr, two curve segments */
    float level, grow, a2, b1, prev, cur, start;
    float end[2], dur[2], curve[2];
    int32_t count, seg, counter, phase;
    uint8_t linear, done;
} d8_env_t;

/* ---- voices ------------------------------------------------------------- */
typedef struct {
    float f0, loop_g, forward, tune_trim, atk_amt, atk_env, accent_v;
    float fb, tone_c, tone_z, dc_z, sigh_env, shp;
    d8_bp_t bt;
    int32_t gate, coef_age, quiet;
    uint8_t active;
} d8_bd_t;

typedef struct {
    float mix1, mix2, accent_v, noise_env, noise_decay, shp;
    d8_bp_t bt1, bt2;
    d8_bq_t noise_hp, out_hp;
    d8_rng_t rng;
    int32_t gate, quiet;
    uint8_t active;
} d8_sd_t;

typedef struct {                    /* one tom/conga channel; the switch is the mode */
    float f0, loop_g, accent_v, fwd, pitch_env, skin_env, skin_lp_c, skin_lp_z;
    float strike_lp_c, strike_lp_z, fb, dc_z, shp;
    d8_bp_t bt;
    d8_rng_t rng;
    int32_t gate, coef_age, quiet;
    uint8_t active, mode;
} d8_tom_t;

typedef struct {
    float g, fb, accent_v, shp;
    d8_bp_t bt;
    int32_t gate, quiet;
    uint8_t active;
} d8_clave_t;

typedef struct {
    float level, atk_c, dec_c, peak;
    d8_hp1_t hpa, hpb;
    d8_rng_t rng;
    int32_t quiet;
    uint8_t rising, active;
} d8_ma_t;

typedef struct {                    /* the sc808 rim shot */
    d8_env_t env;
    float tri_ph, tri_inc;
    uint32_t pul_ph, pul_inc;
    d8_bq_t peak, hp, lp;
    d8_rng_t rng;
    int32_t quiet;
    uint8_t pul_wrap, active;
} d8_rim_t;

typedef struct {
    float tooth, tooth_d, main_level, main_d, main_target, main_atk, floor_level, floor_d;
    d8_bp_t bp;
    d8_bq_t hp;
    d8_rng_t rng;
    int32_t spread, fired, age, main_open, quiet;
    uint8_t active;
} d8_cp_t;

typedef struct {                    /* six Schmitt squares, 0.32 fixed-point phases */
    uint32_t ph[6], inc[6];
    float drift[6], jm1[6];         /* jitter is 1 + jm1 */
    d8_rng_t rng;
    int32_t drift_cnt;
    uint8_t pend_wrap;              /* phases that start at >= 1.0 in 8W8 */
} d8_bank_t;

typedef struct { float v, target, up, down; } d8_menv_t;

typedef struct {
    d8_bq3_t bp1, bp2;
    d8_bp_t sus1, sus2, body_res;
    d8_bq_t body_sk, top_hp, out_hp;
    d8_hp1_t body_hpa, crash_hp, dc;
    float body_lp[2], crash_lp[2], floor_lp[2], top_lp;
    float e1, e2, e3, e1t, d1, d2, d3, atk_c, e1_base;
    int32_t e1_n, quiet;
    uint8_t e1_ramp, active;
} d8_cy_t;

typedef struct {
    d8_bq_t ska, skb;
    d8_hp1_t dc;
    d8_menv_t env;
    float lp_c, lp[5], d1, d2, out_scale;
    float lin_level, lin_step, lin_target, lin_atk_c, lin_base;
    int32_t lin_hold, lin_n, quiet;
    uint8_t mode, linear, ramp, active;
} d8_hat_t;

typedef struct {
    d8_bp_t bp;
    d8_hp1_t hp, bla, blb;
    float clank, body, clank_d, body_d, ratio;
    int32_t quiet;
    uint8_t active;
} d8_cb_t;

/* one output lane: 8W8's per-lane gain, choke fade and Crush state */
typedef struct {
    float hit, cg, cstep, crush[2];
    float pk;                         /* X0X: the hit's peak so far; the tail ends 60 dB under it */
    int32_t qn;                       /* samples in a row under that */
    uint8_t snd;
} d8_lane_t;

typedef struct {                    /* a sound's drive stage, resolved from its pots */
    float drive, k, mk, dn, bm, steps, hold;
} d8_shp_t;

struct drum808 {
    uint8_t pot[D8S_NUM][D8P_NUM];
    uint8_t sw[D8_NUM];               /* LT/MT/HT tom|conga, RS rim|clave, CP clap|maracas */
    uint8_t kpot[3];                  /* kit: level, accent, choke */
    uint8_t tpan[D8_NUM];             /* X0X: each track's pan pot (a track, not a sound: tom / conga share it) */
    float pan_l[D8_NUM], pan_r[D8_NUM];
    float pan_lc[D8_NUM], pan_rc[D8_NUM], pan_dl[D8_NUM], pan_dr[D8_NUM];   /* gliding: now, per sample */
    float potv[D8S_NUM][D8P_NUM];     /* engineering values of pot[] */
    d8_shp_t shp[D8S_NUM];
    float vol, vel_depth;
    int32_t choke;

    d8_bd_t bd;
    d8_sd_t sd;
    d8_tom_t tom[3];
    d8_rim_t rs;
    d8_clave_t cl;
    d8_cp_t cp;
    d8_ma_t ma;
    d8_bank_t bank;
    d8_cb_t cb;
    d8_hat_t ch, oh;
    d8_cy_t cy;
    d8_lane_t lane[13];
};
typedef struct drum808 drum808_t;

void drum808_init(drum808_t *d);                          /* 8W8 defaults */
void drum808_trigger(drum808_t *d, int track, float vel); /* vel 0..1, 1.0 = accent */
void drum808_render(drum808_t *d, float *dry, float *rev, float *dly, int n);
/* X0X stereo: each track placed by its PAN into dry_l / dry_r (sends mono); all centred, both are
 * drum808_render's dry exactly */
void drum808_render_st(drum808_t *d, float *dry_l, float *dry_r, float *rev, float *dly, int n);
/* Only selected tracks reach dry/send buses; every voice still advances normally. */
void drum808_render_st_masked(drum808_t *d, float *dry_l, float *dry_r, float *rev, float *dly,
                             int n, uint16_t audible_tracks);
void drum808_pan_settle(drum808_t *d);   /* every pan to its target at once (the kit is silent: no zipper) */
     /* ADDS this block (mono, n <= 256) into the dry bus and the reverb / delay send buses */
int drum808_nparams(int track);                           /* D8_KIT = kit-wide */
const x0x_param_t *drum808_param(int track, int i);
void drum808_set(drum808_t *d, int track, int i, int value);
int drum808_get(const drum808_t *d, int track, int i);

/* true while any voice is still sounding */
int drum808_active(const drum808_t *d);

/* SPDX-License-Identifier: GPL-3.0-only
 * BLE-HCI ACL start PB flags: preserve received MIDI Note Off and bounds.
 * Compiles the actual ble_midi_host.c, not extracted functions.
 */
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include "ble_midi_host.h"

static unsigned checks, failures, frames;
#define CHECK(x) do { checks++; if (!(x)) { failures++; fprintf(stderr,"FAIL %s:%d: %s\n",__FILE__,__LINE__,#x); } } while (0)

static int sink(uint8_t type, const uint8_t *payload, uint16_t n, void *ctx)
{
    (void)payload; (void)ctx;
    CHECK(n < 128u);
    CHECK(type == BLEH_H4_ACL || type == BLEH_H4_CMD);
    frames++;
    return 0;
}
static void init(bleh_t *h)
{
    bleh_init(h, sink, 0, "X0X37", 0);
    h->state = BLEH_CONNECTED;
    h->conn = 0x0041u;
    h->credits = 4u;
}
static void acl(bleh_t *h, unsigned pb, unsigned connection, const uint8_t *p, unsigned n)
{
    uint8_t b[64];
    CHECK(n <= sizeof b - 4u);
    if (n > sizeof b - 4u) return;
    b[0] = (uint8_t)connection;
    b[1] = (uint8_t)((connection >> 8u) | (pb << 4u));
    b[2] = (uint8_t)n;
    b[3] = (uint8_t)(n >> 8u);
    memcpy(b + 4, p, n);
    bleh_rx(h, BLEH_H4_ACL, b, (uint16_t)(n + 4u));
}
static void no_msg(bleh_t *h)
{
    bleh_msg_t msg;
    CHECK(!bleh_midi_next(h, &msg));
}
static void note_off(bleh_t *h, unsigned note)
{
    bleh_msg_t msg = {0};
    int found = bleh_midi_next(h, &msg);
    CHECK(found == 1);
    if (found != 1) return;
    CHECK(msg.len == 3u);
    CHECK(msg.b[0] == 0x80u);
    CHECK(msg.b[1] == note);
    CHECK(msg.b[2] == 0u);
    no_msg(h);
}
static void test_complete_first(unsigned pb)
{
    bleh_t h;
    /* L2CAP length=8, CID_ATT=4, ATT Write Command handle 6,
     * BLE-MIDI header 0x80, low timestamp 0x80, Note Off 0x80 0x3c 0x00. */
    static const uint8_t p[] = {8,0,4,0,0x52,6,0,0x80,0x80,0x80,60,0};
    init(&h);
    acl(&h, pb, 0x41, p, sizeof p);
    note_off(&h, 60u);
    CHECK(h.rx_on == 0u);
}
static void test_fragmented_first(unsigned pb)
{
    bleh_t h;
    static const uint8_t p[] = {8,0,4,0,0x52,6,0,0x80,0x80,0x80,61,0};
    init(&h);
    acl(&h, pb, 0x41, p, 6u);
    CHECK(h.rx_on == 1u);
    CHECK(h.rx_have == 6u && h.rx_need == 12u);
    no_msg(&h);
    acl(&h, 1u, 0x41u, p + 6u, sizeof p - 6u);
    note_off(&h, 61u);
    CHECK(h.rx_on == 0u);
}
static void test_bad_and_boundary(void)
{
    bleh_t h;
    static const uint8_t p[] = {8,0,4,0,0x52,6,0,0x80,0x80,0x80,62,0};
    static const uint8_t too_large[] = {24,0,4,0};
    static const uint8_t wrong_cid[] = {8,0,9,0};
    static const uint8_t extraneous[] = {1,2,3,4,5,6,7};
    init(&h);
    acl(&h, 1u, 0x41u, p + 6, sizeof p - 6u); /* orphan continuation */
    no_msg(&h);
    acl(&h, 0u, 0x42u, p, sizeof p); /* wrong connection handle */
    no_msg(&h);
    acl(&h, 0u, 0x41u, too_large, sizeof too_large); /* L2CAP > ATT MTU */
    CHECK(h.rx_on == 0u);
    acl(&h, 0u, 0x41u, wrong_cid, sizeof wrong_cid);
    CHECK(h.rx_on == 0u);
    acl(&h, 0u, 0x41u, p, 6u);
    CHECK(h.rx_on == 1u);
    acl(&h, 1u, 0x41u, extraneous, sizeof extraneous); /* overshoots assembled length */
    CHECK(h.rx_on == 0u);
    no_msg(&h);
    acl(&h, 3u, 0x41u, p, 6u); /* complete flag must not leave partial PDU armed */
    CHECK(h.rx_on == 0u);
    acl(&h, 2u, 0x41u, p, sizeof p); /* recovery via flushable first */
    note_off(&h, 62u);
    acl(&h, 0u, 0x41u, p, 6u);
    CHECK(h.rx_on == 1u);
    acl(&h, 0u, 0x41u, p, sizeof p); /* new first resets incomplete old PDU */
    note_off(&h, 62u);
    CHECK(h.rx_on == 0u);
}
int main(void)
{
    test_complete_first(0u);  /* first non-flushable */
    test_complete_first(2u);  /* first flushable */
    test_complete_first(3u);  /* complete PDU: no continuation */
    test_fragmented_first(0u);
    test_fragmented_first(2u);
    test_bad_and_boundary();
    printf("BLE ACL start PB flags: %u checks, %u failures, controller frames=%u\n",checks,failures,frames);
    return failures ? 1 : 0;
}
